    elif pt is not None:
        ended = "waiting"
    elif end is not None:
        ended = end["ended_by"]
    else:
        ended = "harness-fault"

    obs = {}
    if end is not None and isinstance(end.get("observe"), dict):
        obs = end["observe"]
    if pt is not None:
